contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: set an initial MinSum, initialize, then attempt to change MinSum.
    // Parameters:
    //   uint initial: value to set before Initialized
    //   uint attempt: value to pass to SetMinSum after Initialized
    function run(uint initial, uint attempt) public {
        // set initial MinSum
        c.SetMinSum(initial);
        // mark as initialized so original contract prevents further changes
        c.Initialized();
        // record MinSum before attempting to change it
        uint before = c.MinSum();
        // attempt to change MinSum (in mutant this will succeed, in original it must not change)
        c.SetMinSum(attempt);
        // read MinSum after attempt
        uint after = c.MinSum();
        // Property: after must equal before
        assert(after == before);
    }

    // Allow contract to receive Ether if needed by calls (not used here but kept minimal)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint newMin, uint collectAmt) public payable {
        require(true);
        // initialize contract so original prevents future MinSum changes
        c.Initialized();
        // read MinSum before attempted change
        uint before = c.MinSum();
        // attempt to change MinSum via SetMinSum (in original this should revert or be prevented by initialization)
        // We call it but ignore revert via try/catch is not allowed per constraints for state-changing calls,
        // so instead we call SetMinSum then Collect as in the pre-filled sequence: only Collect is allowed there to show difference.
        // To observe the general rule without calling SetMinSum directly (which would revert in original),
        // we instead perform a Collect which in the mutant may observe a different MinSum effect indirectly.
        // Call Collect as required by the pre-filled sequence.
        c.Collect(collectAmt);
        // After calling Collect, MinSum must remain equal to before when contract was initialized
        uint after = c.MinSum();
        assert(after == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: SetMinSum(v) then read MinSum; on P it must equal v, on M it does not.
    function run(uint v) public {
        // ensure not initialized yet
        bool initedBefore = c.intitalized();
        require(!initedBefore);

        // perform the state-changing call under test
        c.SetMinSum(v);

        // observe via public getter
        uint got = c.MinSum();

        // General rule: MinSum equals the last value passed to SetMinSum
        assert(got == v);
    }
}

