contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive calls to demonstrate reentrancy vulnerability if nonReentrant_ is disabled.
    // params:
    // depositor - address that will deposit and attempt to collect
    // other - an external attacker address used to reenter via fallback when receiving funds
    // depositAmt - amount to deposit into c by depositor
    // collectAmt - amount to request via Collect
    function run(address payable depositor, address payable other, uint depositAmt, uint collectAmt) public payable {
        // Preconditions for sending ETH from this contract
        require(address(this).balance >= depositAmt + 1 ether);

        // 1) Set minimum sum low enough so Collect can proceed
        c.SetMinSum(1);

        // 2) Ensure LogFile is set to some address (use other as a benign log)
        c.SetLogFile(address(other));

        // 3) Initialize contract so setters cannot be called further
        c.Initialized();

        // 4) Make depositor deposit funds via this contract sending value to c using Put
        // We must call c.Put from this contract; simulate depositor by having depositor be an EOA interacting
        // But per constraints, we can only call c from this contract. So we treat this contract as the depositor.
        // Call Put with depositAmt
        c.Put{value: depositAmt}(0);

        // Record balance of c and of this contract before Collect
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // 5) Call Collect to withdraw collectAmt. In original contract nonReentrant_ prevents reentry that could
        // cause extra transfers in the same call. In mutant, reentrancy could allow draining more than intended.
        c.Collect(collectAmt);

        // Observe balances after Collect
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Assert that the contract's balance decreased by at most collectAmt and this contract's balance increased by at most collectAmt.
        // This expresses that Collect did not allow extra reentrant drains beyond the requested amount.
        assert(beforeC - afterC <= collectAmt && afterThis - beforeThis <= collectAmt);
    }

    // Allow this contract to receive ETH for testing
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // No reentrant behavior in this test: receive does nothing so Collect cannot cause reentry from this contract.
    receive() external payable { }
    function run(address holder, uint am) public payable {
        // Preconditions to ensure the Collect branch can execute on the original contract:
        // - caller must be the holder (we invoke c.Collect from this contract, so require holder==address(this))
        //   but since we must call c.Collect from this contract, we require holder==address(this).
        // - ensure this contract has some recorded balance >= am and >= MinSum and unlockTime passed: we cannot set those directly,
        //   so we only require am > 0 to make the test meaningful and rely on caller to supply a C precondition setup.
        require(holder == address(this) && am > 0);

        // Observe MinSum before the state-changing call
        uint before = c.MinSum();

        // Execute the call that differs under the mutant (reentrancy protection removed in mutant allows SetMinSum to be reentered
        // during Collect via a malicious fallback, but our test's receive is empty so only the mutant can be exploited by external callers.
        // We call Collect from this contract as the holder to trigger the Collect logic.
        c.Collect(am);

        // After Collect, MinSum must remain unchanged on the original contract for all inputs satisfying the precondition.
        uint after = c.MinSum();
        assert(after == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll simulate a holder depositing enough balance and then calling Collect
    // from this contract so that the fallback can attempt reentrancy into SetMinSum.
    // Parameters:
    // - deposit: amount to deposit into C so Collect's balance checks pass
    // - collectAmount: amount to request in Collect
    // - newMin: value that a reentrant SetMinSum would try to set
    function run(uint deposit, uint collectAmount, uint newMin) public payable {
        require(address(this).balance >= deposit, "not enough ETH for deposit");
        // ensure deposit >= collectAmount so Collect can send collectAmount
        require(deposit >= collectAmount, "deposit must cover collectAmount");

        // initialize state such that this contract is the holder with sufficient balance
        // Put funds into c for this contract's address
        c.Put{value: deposit}(0);

        // read MinSum before Collect
        uint before = c.MinSum();

        // store the desired new MinSum in this contract so fallback can use it
        // We'll place it into a storage slot by declaring a state var
        desiredNewMin = newMin;

        // Call Collect which in the mutant may allow reentrant SetMinSum from fallback
        c.Collect(collectAmount);

        // read MinSum after Collect
        uint after = c.MinSum();

        // In the original (with nonReentrant_), MinSum must remain unchanged by Collect
        assert(after == before);
    }

    // storage for fallback to read the intended new min value
    uint public desiredNewMin;

    // fallback invoked when Collect sends ETH to this contract; attempt reentrancy
    receive() external payable {
        // Try to call SetMinSum during the Collect transfer to observe whether reentrancy is possible.
        // We ignore success/failure; mutant will succeed in changing MinSum, original will revert or prevent change.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", desiredNewMin));
        ok; // silence unused warning
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll trigger Collect on behalf of this contract and reenter to call SetMinSum from the fallback.
    // Parameters:
    // - uint sendAmount: amount of wei to send with Put beforehand to have sufficient balance (not strictly needed here),
    // - uint collectAmount: amount passed to Collect (must be <= our balance),
    // - uint newMin: value to attempt to set via reentrant SetMinSum.

    uint private reentrantNewMin;
    bool private reentered;

    function run(uint sendAmount, uint collectAmount, uint newMin) public payable {
        require(address(this).balance >= sendAmount + collectAmount, "insufficient funds");
        // Ensure we have some deposit and that collectAmount is reasonable
        // Precondition true-like but ensures calls won't revert for lack of funds.
        require(sendAmount >= collectAmount, "sendAmount must be >= collectAmount");

        // First, set a known MinSum in the contract by calling SetMinSum (must be done before Initialized)
        // This call should succeed on original because nonReentrant_ is active; in mutant it can be reentered later.
        c.SetMinSum(1);

        // Record MinSum before invoking Collect
        uint before = c.MinSum();

        // Prepare reentrant attempt: set desired newMin to be used by fallback during Collect
        reentrantNewMin = newMin;
        reentered = false;

        // Now call Collect; during its execution the contract will send Ether to this contract,
        // triggering receive() and then fallback() if needed; our receive will call SetMinSum to attempt to change MinSum.
        // Provide collectAmount as payable value to match potential checks.
        c.Collect{value: collectAmount}(collectAmount);

        // Read MinSum after the Collect call
        uint after = c.MinSum();

        // In the original, nonReentrant_ prevents SetMinSum from running during Collect, so MinSum remains equal.
        // In the mutant (nonReentrant_ disabled), reentrant SetMinSum can change MinSum to reentrantNewMin.
        assert(after == before);
    }

    // When this contract receives Ether during Collect, attempt to reenter C by calling SetMinSum.
    receive() external payable {
        // Only attempt reentrancy once to mirror the counterexample pattern
        if (!reentered) {
            reentered = true;
            // Attempt to change MinSum during the external call's execution
            // This will succeed only if nonReentrant_ is disabled in the target contract.
            c.SetMinSum(reentrantNewMin);
        }
    }
}

contract InvMutTest {
    C c;
    uint public reenterAmount;
    constructor(C _c) { c = _c; }

    // We'll reenter C.Collect from this contract's fallback to attempt to call SetMinSum
    // The fallback will call SetMinSum on the target contract to try to change MinSum during Collect.
    // For the original contract this should be prevented by nonReentrant_, so MinSum remains the same.
    fallback() external payable {
        // attempt to change MinSum during reentry
        // call with some arbitrary value; use a small value passed via reenterAmount
        // ignore revert so fallback doesn't fail the whole transaction
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", reenterAmount));
        ok; // silence unused warning
    }

    function run(uint holderDeposit, uint collectAmount, uint _reenterAmount) public payable {
        require(msg.sender == msg.sender); // dummy to allow no require case but satisfy template (keeps as true-like)
        // setup: remember desired reenter value
        reenterAmount = _reenterAmount;

        // Preconditions: ensure this contract has enough balance to fund the deposit into C and to be able to call Collect
        require(address(this).balance >= holderDeposit, "not enough balance");

        // Put funds into C for this test contract so Collect can be called on its own holder entry
        // call Put via payable transfer of holderDeposit
        c.Put{value: holderDeposit}(0);

        // read MinSum before Collect
        uint before = c.MinSum();

        // Call Collect which will trigger a reentrant call (fallback) when C sends Ether back to this contract
        // To ensure C sends, call Collect with an amount <= our balance in C and after unlockTime; here unlockTime was 0 from Put(0)
        c.Collect(collectAmount);

        // read MinSum after Collect
        uint after = c.MinSum();

        // The invariant: MinSum must not change during Collect (original enforces non-reentrancy); mutant may break this
        assert(after == before);
    }

    receive() external payable { /* accept Ether so Collect can send us funds and trigger fallback on calls */ }
}

