pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to deposit (value), lockTime for put, and an arbitrary minVal to try to set
    // We will deploy an attacker contract that on receiving funds will re-enter Collect to try to call SetMinSum via calling SetMinSum through C's public API (SetMinSum is public), demonstrating that with nonReentrant disabled MinSum can change.
    function testFuzz_property(uint128 depositAmount, uint64 lockTime, uint256 newMin) public {
        // keep values in reasonable ranges but wide enough
        vm.assume(depositAmount > 0);
        depositAmount = uint128(bound(uint256(depositAmount), 1, 1e18));
        lockTime = uint64(bound(uint256(lockTime), 0, 10000));

        // deploy attacker helper with reference to c
        Attacker attacker = new Attacker(c);

        // fund attacker so it can call Put
        vm.deal(address(attacker), uint256(depositAmount));

        // 1) set an initial MinSum via owner-like call (any caller can call SetMinSum before initialized flag flips)
        // use this contract as caller to set MinSum to 0 (baseline)
        c.SetMinSum(0);

        // 2) attacker performs Put to increase its balance and set unlockTime
        // attacker will receive funds and be able to call Collect; ensure unlockTime is in the past so Collect can succeed
        // Set unlockTime small so block.timestamp > unlockTime holds after warp
        vm.warp(block.timestamp + 100);

        // Have attacker call Put with _lockTime = 0 so unlockTime <= current timestamp
        attacker.doPut{value: uint256(depositAmount)}(uint256(lockTime));

        // record MinSum before Collect
        uint256 beforeMin = c.MinSum();

        // Now make attacker attempt to Collect a small amount; during its fallback/receive it will re-enter C.SetMinSum(newMin)
        // so if nonReentrant_ is disabled, MinSum will change; otherwise it remains the same.
        // Make sure attacker has enough balance and criteria: depositAmount >= MinSum and >= am and block.timestamp > unlockTime
        uint256 collectAmount = 1;
        vm.warp(block.timestamp + 200);

        // trigger Collect from attacker
        bool ok;
        try attacker.doCollect(collectAmount, newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: the reference contract never changes MinSum during Collect (so MinSum equals beforeMin)
        // the mutant with disabled nonReentrant_ can be re-entered and change MinSum, making this assert fail for some inputs
        assertTrue(c.MinSum() == beforeMin);
    }
}

// Minimal attacker that re-enters C during collection by calling SetMinSum in its receive
contract Attacker {
    C public target;
    uint256 public reenterNewMin;

    constructor(C _t) payable {
        target = _t;
    }

    // deposit into C
    function doPut(uint256 lockTime) external payable {
        // call Put on target
        target.Put{value: msg.value}(lockTime);
    }

    // request to Collect; set the desired newMin to try to set during reentrancy
    function doCollect(uint256 am, uint256 newMin) external {
        reenterNewMin = newMin;
        // call Collect; when funds are sent to this contract (via call), its receive() will run and attempt re-entry
        target.Collect(am);
    }

    // receive will be invoked when target sends Ether; attempt to re-enter target.SetMinSum
    receive() external payable {
        // try to call SetMinSum during the receive; this will succeed only if nonReentrant_ is disabled
        // ignore any revert to allow Collect flow to continue
        try target.SetMinSum(reenterNewMin) {
        } catch {}
    }
}

