pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attackerSent (amount attacker sends to Put via fallback/Put), newMin (value attacker will attempt to set via SetMinSum in reentrant call), lockTime
    function testFuzz_property(uint128 attackerSent, uint64 lockTime, uint256 newMin) public {
        // keep values in wide but reasonable bounds
        uint256 sendAmt = bound(uint256(attackerSent), 1, 1 ether);
        uint256 lt = uint256(lockTime % 100000); // limit lockTime to manageable range

        // deploy attacker and fund it
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), sendAmt + 1 ether);

        // initialize c: set MinSum to some value that attacker will try to change
        uint256 initialMin = 1 ether;
        // Use an external caller to set MinSum before initialized flag is set
        c.SetMinSum(initialMin);
        // set LogFile to attacker's address so Put/Collect will log through attacker (no special need but keep consistent)
        c.SetLogFile(address(attacker));
        // mark contract initialized so subsequent SetMinSum calls revert unless reentered under buggy mutant
        c.Initialized();

        // attacker funds its account on C by calling fallback which routes to Put(0)
        // attacker will call Put with lockTime to set unlockTime such that Collect can be executed
        attacker.prepare{value: sendAmt}(lt);

        // ensure attacker has balance on the C contract >= MinSum so Collect's branch may execute
        // If sendAmt is smaller than initialMin, increase attacker's balance by additional direct Put
        if (sendAmt < initialMin) {
            uint256 extra = initialMin - sendAmt;
            // top up attacker externally and call Put again
            vm.deal(address(attacker), extra);
            attacker.prepare{value: extra}(lt);
        }

        // record MinSum before Collect
        uint256 before = c.MinSum();

        // attempt Collect from attacker; this may trigger reentrant SetMinSum in mutant via attacker's receive
        bool ok;
        try attacker.callCollect(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect completes, the reference guarantees MinSum unchanged for all inputs
        // The mutant that removed nonReentrant_ may allow reentrant SetMinSum and thus change MinSum
        assertTrue(c.MinSum() == before);
    }
}

// Attacker contract that will re-enter C during Collect by using its receive to call SetMinSum
contract Attacker {
    C c;
    address owner;
    uint256 toSet;

    constructor(address _c) {
        c = C(_c);
        owner = msg.sender;
    }

    // prepare: call fallback/Put by sending value and supplying lockTime via explicit Put
    function prepare(uint256 lockTime) external payable {
        // call Put by invoking fallback which forwards to Put(0) in C; but we want to call Put(lockTime)
        // So call Put directly
        c.Put{value: msg.value}(lockTime);
    }

    // called by test to trigger Collect from this contract
    function callCollect(uint256 am) external {
        // call Collect; during the external call we will reenter via receive
        c.Collect{value: 0}(am);
    }

    // receive will attempt to re-enter and call SetMinSum - this models the adversarial reentrant behavior
    receive() external payable {
        // try to set MinSum to a different value
        // We ignore reverts from SetMinSum (in reference it should revert due to initialized flag or nonReentrant_)
        // but in the mutant without nonReentrant_ it may succeed and modify MinSum
        // We choose a nonzero value derived from gas/tx to vary across fuzz runs
        uint256 candidate = uint256(uint160(address(this))) % 1 ether + 1;
        // attempt to call SetMinSum; swallow failure
        try c.SetMinSum(candidate) {
        } catch {
        }
    }
}

