pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: attackerStartMin (value attacker will try to set via SetMinSum), deposit amount, collect amount
    function testFuzz_property(uint256 attackerStartMin, uint256 deposit, uint256 collectAmt) public {
        // keep values in wide but sensible ranges
        deposit = bound(deposit, 1, 1 ether);
        collectAmt = bound(collectAmt, 1, 1 ether);
        attackerStartMin = bound(attackerStartMin, 0, 1 ether);

        // deploy attacker contract that will reenter during Collect and call SetMinSum
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can deposit and trigger Collect
        vm.deal(address(attacker), 2 ether);

        // initialize C: set LogFile to attacker (it is just some address but SetLogFile requires only address)
        // and set MinSum to a known value via calling SetMinSum before Initialized (allowed once)
        // use an externally owned account to call these setup functions
        address admin = address(0xABCD);
        vm.deal(admin, 1 ether);
        vm.prank(admin);
        c.SetLogFile(address(attacker));
        vm.prank(admin);
        c.SetMinSum(0);

        // attacker will deposit funds by calling Put (fallback calls Put(0)); make attacker send deposit
        attacker.deposit{value: deposit}();

        // record MinSum before attack
        uint256 before = c.MinSum();

        // attacker is configured to attempt to set MinSum to attackerStartMin when reentering
        attacker.setTargetMin(attackerStartMin);

        // trigger Collect from attacker which will attempt reentrancy during fallback/call
        // If reference contract has nonReentrant_ properly, attacker cannot reenter to call SetMinSum; otherwise it can
        attacker.triggerCollect(collectAmt);

        // exactly one assertion reading c: on the correct contract, MinSum must still equal before for ALL inputs
        // the mutant (without nonReentrant_) can change MinSum during reentrant SetMinSum, so for some inputs it will differ
        assertTrue(c.MinSum() == before);
    }
}

// minimal attacker that reenters during Collect by making a call back into C and calling SetMinSum
contract Attacker {
    C immutable target;
    uint256 public targetMin;
    bool public reentered;

    constructor(address _t) payable {
        target = C(_t);
    }

    function setTargetMin(uint256 _m) public {
        targetMin = _m;
    }

    // deposit by invoking fallback on C which will route to Put(0)
    function deposit() public payable {
        (bool s,) = address(target).call{value: msg.value}("");
        require(s);
    }

    // trigger Collect from this contract so that during Collect the contract can attempt reentrancy
    function triggerCollect(uint256 _am) public {
        // call Collect from this contract so msg.sender inside C is this attacker and any low-level calls target back here
        target.Collect(_am);
    }

    // fallback is payable and will be invoked if C makes a call back to msg.sender during Collect;
    // when invoked, attempt to call SetMinSum on target to change MinSum
    fallback() external payable {
        // prevent nested reentry loops
        if (!reentered) {
            reentered = true;
            // try to set MinSum to the chosen value
            // ignore failures
            try target.SetMinSum(targetMin) {
            } catch {
            }
        }
    }
}

