pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params:
    // attackerInitialFunds: ether funded to attacker to perform Put and to pay for reentrant calls
    // depositAmt: amount to deposit via Put (must be >= collectAmt and >= MinSum later)
    // collectAmt: amount attacker will request to Collect
    // newMin: value attacker will set via reentrant SetMinSum during Collect
    function testFuzz_property(uint256 attackerInitialFunds, uint256 depositAmt, uint256 collectAmt, uint256 newMin) public {
        // keep values in wide but sensible ranges
        attackerInitialFunds = bound(attackerInitialFunds, 1 wei, 10 ether);
        depositAmt = bound(depositAmt, 1 wei, attackerInitialFunds);
        // allow collectAmt up to depositAmt
        collectAmt = bound(collectAmt, 0 wei, depositAmt);
        newMin = bound(newMin, 0, type(uint256).max);

        // Deploy attacker contract which will reenter during Collect and call SetMinSum
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), newMin);

        // fund attacker so it can Put and be the caller when reentering
        vm.deal(address(attacker), attackerInitialFunds);

        // initialize C's state: set an initial MinSum to a different value than newMin so change is observable
        // use an external actor (this) to call SetMinSum before Initialized is set; SetMinSum is nonReentrant_ protected
        // Ensure initialization not yet set in contract (default false)
        // call SetMinSum to some value (e.g., 1 wei) via direct call
        c.SetMinSum(1);

        // now have attacker deposit funds by calling Put (attacker's fallback will not be used now)
        attacker.deposit{value: depositAmt}();

        // record MinSum before Collect
        uint256 before = c.MinSum();

        // Now perform Collect from attacker which will attempt to reenter and call SetMinSum(newMin)
        // attacker contract will call c.Collect which triggers its fallback to reenter
        // Ensure attacker has enough balance in its recorded holder: depositAmt satisfied above
        // call Collect on attacker which will in turn call c.Collect as attacker
        bool ok;
        try attacker.doCollect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: on the correct contract, MinSum must remain equal to before for ALL inputs
        // (the nonReentrant_ modifier prevents reentrant SetMinSum during Collect)
        // The buggy mutant that removes the guard can be reentered and change MinSum, making this fail for some inputs
        assertTrue(c.MinSum() == before);
    }
}

// Minimal reentrant attacker: calls Collect on C, and in its fallback reenters to call SetMinSum
contract ReentrantAttacker {
    C target;
    uint256 newMin;
    address owner;

    constructor(address _t, uint256 _newMin) payable {
        target = C(_t);
        newMin = _newMin;
        owner = msg.sender;
    }

    // deposit into target on behalf of this contract
    function deposit() external payable {
        // call Put with some lock time 0
        target.Put{value: msg.value}(0);
    }

