    function testFuzz_property(address depositor, uint96 depositAmt, uint32 lockTime, uint96 collectAmt) public {
        // admissible domain: nonzero deposit, collect equals deposit (we'll try to collect exactly what was deposited)
        vm.assume(depositAmt > 0);
        // ensure collectAmt equals depositAmt to test exact withdrawal behavior
        // but keep it as a fuzz param by bounding collectAmt to depositAmt and require equality
        collectAmt = uint96(bound(collectAmt, 0, depositAmt));
        vm.assume(collectAmt == depositAmt);

        // setup: initialize contract minimum and logging to some benign address
        // set MinSum to 1 so deposits >=1 are eligible
        c.SetMinSum(1);

        // ensure depositor has enough balance
        vm.deal(depositor, depositAmt);

        // record previous unlockTime and balance
        uint prevUnlock = c.Acc(depositor).unlockTime();
        uint prevBal = c.Acc(depositor).balance();

        // make the Put call from depositor with value depositAmt
        vm.prank(depositor);
        c.Put{value: depositAmt}(lockTime);

        // after Put, if block.timestamp+lockTime > prevUnlock then unlockTime must equal that sum
        // compute expected unlock candidate
        uint expectedUnlock = block.timestamp + lockTime;
        uint gotUnlock = c.Acc(depositor).unlockTime();
        if (expectedUnlock > prevUnlock) {
            // enforce that the contract updated unlockTime to expected value
            // this is part of admissible domain to ensure Collect later can depend on unlockTime
            // use require to restrict traces where reference behavior holds; mutant also updates unlockTime, so this keeps domain valid
            require(gotUnlock == expectedUnlock);
        }

        // fast-forward time beyond unlock to allow Collect
        vm.warp(block.timestamp + 1 + lockTime);

        // ensure stored balance before Collect is at least depositAmt in the reference; capture before Collect
        uint balBefore = c.Acc(depositor).balance();

        // try Collect of collectAmt (which equals depositAmt)
        vm.prank(depositor);
        // wrap in try/catch to satisfy requirements if revert differing
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // If Collect succeeded, the reference contract always deducts the withdrawn amount from Acc[depositor].balance
        // We assert that when Collect did not revert, the new balance equals balBefore - collectAmt.
        if (ok) {
            uint balAfter = c.Acc(depositor).balance();
            assertTrue(balAfter == balBefore - collectAmt);
        } else {
            // If Collect reverted, require that condition for Collect was not met (so reference would revert too).
            // The reference reverts only if preconditions fail; in admissible domain we ensured depositAmt>0 and MinSum=1,
            // but Collect can still revert if balBefore < collectAmt or block.timestamp <= unlockTime.
            // We assert that in case of revert, it must be because balBefore < collectAmt (since we warped past unlock),
            // otherwise the reference would have succeeded. This keeps the specification universal over admissible inputs.
            require(balBefore < collectAmt || block.timestamp <= c.Acc(depositor).unlockTime());
        }
    }
}

